{
  "technical_and_design_decisions": [
    "Baseline the increment on Java 17+ and Spring Framework 6.0, consistent with the specification's minimum requirements.",
    "Implement U1 using RxJava 3 (RxJava 1.x is end-of-life) as a stream processor module that subscribes to input messages, applies an RxJava operator chain, and emits processed messages on the output channel.",
    "Treat U2 as a spike only: deliverables are a design specification and phased roadmap, not production code; candidate approach evaluated is Spring Security ACL integration with the XD runtime's admin server and DSL shell.",
    "Treat U3 as a spike only: use Java Flight Recorder (JFR) and async-profiler to capture startup CPU profiles; deliverable is an analysis document with bottlenecks, reasons, and pros/cons.",
    "Implement U4/U5 by extending the module repository abstraction with an HDFS-backed ModuleRepository that reads/writes custom module uber-jars via the Apache Hadoop FileSystem API, relying on HDFS NameNode HA and DFS client failover for reliability and re-installation after failure.",
    "Implement U6 by exposing the HDFS base location as an externalized Spring Boot configuration property (xd.hadoop.fs.uri / module storage path) overridable via environment variables and the Cloud Foundry application manifest.",
    "Implement U7 by exposing the YARN configuration directory as an externalized configuration property (xd.hadoop.config location) overridable via environment variables and the CF manifest, wired into Hadoop Configuration construction.",
    "Implement U8 by adding a job-stop capability to the job lifecycle: a shell/REST 'job stop' command that resolves the Spark application's YARN application ID and issues a kill via the YARN ResourceManager client API.",
    "U4 and U5 are duplicate user stories and are implemented once as a single work item.",
    "Use JUnit 5 and Mockito for unit tests; use Hadoop MiniDFSCluster / a shared integration HDFS-YARN cluster for integration tests."
  ],
  "assumptions": [
    "All effort is performed by one developer (the author); estimates are effort in workdays (8 hours per workday), not elapsed calendar time.",
    "An existing Spring XD-based codebase, build system (Gradle multi-module build), and CI pipeline are available and do not need to be created from scratch.",
    "Test environments are available at no setup cost beyond configuration: an HDFS cluster with HA NameNodes, a YARN cluster running Spark jobs, and a Cloud Foundry foundation.",
    "U2 (ACL) and U3 (startup profiling) are time-boxed spikes whose only deliverables are documents; no production implementation is included in this increment for those stories.",
    "U4 and U5 are identical duplicates and are counted once.",
    "No UI implementation is required for U2; only identification of DSL and UI scope is in scope per the spike description.",
    "Spark jobs are deployed on YARN, so 'stop an existing Spark job' means killing the corresponding YARN application and updating the job lifecycle state.",
    "Existing module deployment flows remain unchanged except for adding HDFS as a supported module storage backend and the two new configuration override properties.",
    "Product owner is available for acceptance of spike documents and completed stories without material delay."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment planning and baseline setup",
      "activity_description": "Review all user stories, confirm acceptance criteria, set up feature branches, configure development environment (Java 17, Hadoop client libs, profiler tooling access).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Design RxJava processor module",
      "activity_description": "Define module options, processor contract, operator-chain configuration model, and error/backpressure handling strategy for the RxJava-based processor.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Implement RxJava processor module",
      "activity_description": "Implement the RxJava 3 processor module: input channel subscription, configurable operator chain, output emission, and module metadata/options.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Unit tests",
      "activity_description": "Write unit tests covering transformation logic, operator configuration, error handling, and backpressure behavior.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "U1 - Integration tests and stream verification",
      "activity_description": "Deploy the module in a sample stream on a local XD runtime, verify end-to-end processing, and add integration tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Spike: review customer ACL use cases",
      "activity_description": "Collect and analyze customer use cases for per-user, per-resource access control to derive ACL requirements.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "U2 - Spike: evaluate approach for XD runtime",
      "activity_description": "Evaluate candidate approaches (e.g., Spring Security ACL integration, custom interceptor) against XD admin server, container, and module runtime architecture; select best fit.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "U2 - Spike: write ACL design specification",
      "activity_description": "Document the chosen ACL design: model (user, resource, privileges), storage, enforcement points, and administration operations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "U2 - Spike: DSL/UI scope and phased roadmap",
      "activity_description": "Identify the scope of DSL and UI changes required for ACL management and document next steps and implementation phases.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "U3 - Spike: set up profiling tooling",
      "activity_description": "Configure JFR and async-profiler for the admin and container server startup paths and prepare repeatable startup benchmarks.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A11",
      "activity_name": "U3 - Spike: profile admin server startup",
      "activity_description": "Capture and analyze CPU profiles of admin server startup; isolate hot spots (classpath scanning, bean initialization, autoconfiguration).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "U3 - Spike: profile container server startup",
      "activity_description": "Capture and analyze CPU profiles of container server startup; isolate hot spots specific to module loading and runtime wiring.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "U3 - Spike: document findings",
      "activity_description": "Document identified bottlenecks, root-cause reasons, and pros/cons of candidate optimizations.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A14",
      "activity_name": "U4/U5 - Design HDFS module repository",
      "activity_description": "Design the HDFS-backed module repository: storage layout for uber-jars, HA read path via NameNode failover, and reinstall-on-failure semantics.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "U4/U5 - Implement HDFS module repository",
      "activity_description": "Implement the HDFS ModuleRepository (write on module upload, HA-aware read on resolution, reinstall logic after node failure) using the Hadoop FileSystem API.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A16",
      "activity_name": "U4/U5 - Unit tests",
      "activity_description": "Write unit tests for upload, resolution, listing, deletion, and failover/retry logic using mocks and MiniDFSCluster.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A17",
      "activity_name": "U4/U5 - Integration tests with failure scenarios",
      "activity_description": "Run integration tests on a real HA-enabled HDFS cluster, including NameNode failover and container restart/reinstall scenarios.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A18",
      "activity_name": "U6 - Implement HDFS location override",
      "activity_description": "Add externalized configuration property for the HDFS module storage location, wire it into the HDFS repository and admin server, and support override via CF environment variables/manifest.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A19",
      "activity_name": "U6 - Tests for HDFS location override",
      "activity_description": "Write unit and integration tests verifying default behavior and override via properties, environment variables, and CF deployment.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A20",
      "activity_name": "U7 - Implement YARN config location override",
      "activity_description": "Add externalized configuration property for the YARN configuration directory, wire it into Hadoop Configuration construction, and support override via CF environment variables/manifest.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A21",
      "activity_name": "U7 - Tests for YARN config location override",
      "activity_description": "Write unit and integration tests verifying default behavior and override via properties, environment variables, and CF deployment.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A22",
      "activity_name": "U8 - Design Spark job stop semantics",
      "activity_description": "Define job-stop lifecycle semantics: state transitions, idempotency, error handling, and mapping of XD job to YARN application ID.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A23",
      "activity_name": "U8 - Implement stop support in runtime",
      "activity_description": "Implement the stop capability that resolves the running Spark job's YARN application and issues a kill via the ResourceManager client API, updating job state.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A24",
      "activity_name": "U8 - Shell and REST stop command",
      "activity_description": "Add 'job stop' to the REST API and DSL shell, including validation, status reporting, and security checks.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A25",
      "activity_name": "U8 - Unit and integration tests",
      "activity_description": "Write unit tests for stop logic and integration tests that launch a Spark job on YARN and stop it, verifying resource cleanup.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A26",
      "activity_name": "Documentation",
      "activity_description": "Update reference documentation: RxJava module usage, HDFS module storage configuration, new override properties (U6/U7), job stop command, and spike report links.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A27",
      "activity_name": "Code review, rework, build/CI and packaging",
      "activity_description": "Address review feedback, update build dependencies and CI jobs (Hadoop/RxJava libs, integration test profiles), and produce release artifacts.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 62.5
  }
}
